// ============================================================================
// 文件名  : cjk16_font.v
// 所在位置: assets/v2/masters/font/cjk16_font.v  （母版数据，尚未接入 rtl/）
// 所属层次: OSD 层 / 16x16 中文点阵字模 ROM（数据源，供后续 RTL 阶段接入）
// ============================================================================
// 【一】本文件是什么
//   465 个中文/全角字形，每个 16x16 点阵，每行 16 bit（bit15 = 最左像素），
//   共 16 行。给 {字形索引, 行号} 返回该行的 16 个像素。
//   纯组合查表，无时钟、无状态，同拍出图。

// 【二】为什么是 16x16
//   现有 rtl/osd/osd_font8x16.v 只有 8x16 的英文/数字，拼不出「日常模式」
//   「高温报警」这类中文。16x16 是 640x480 下单行中文可读的最小粒度：
//   8x8 的汉字笔画会粘连，实测不可辨认。

// 【三】字形来源与许可
//   栅格化自 Noto Sans SC Regular（SIL Open Font License 1.1），
//   **刻意不用微软雅黑/黑体/等线**（微软专有字体，随工程分发点阵有授权风险）。
//   项目授权说明见 docs/science_font_attribution.md 与 docs/OFL-NotoSansSC.txt。
//   运行时**不加载任何字体文件**，只分发本文件的点阵常量。

// 【四】重新生成
//   python scripts/gen_assets_v2_font.py
//   生成脚本自带自检：无空字形 / 墨点率合理 / 无切边 / 字形互不相同 /
//   .hex 回读逐位一致 / preview.png 可重新打开。

// 【五】资源代价
//   465 字形 x 16 行 x 16 bit = 119,040 bit 常量。
//   综合成 LUT 查表（不用 BRAM：BRAM 读延迟 1 拍，OSD 需与像素同拍组合）。
//   注意：接入 RTL 前请与 rtl-engineer 确认字库容量预算（BRAM9K/LUT 余量）。

// 【六】索引约定
//   glyph 位宽 9 bit（覆盖 0..464），row 位宽 4 bit（0..15，0 = 最上行）。
//   未收录索引走 default 输出 16'h0000（屏幕表现为空白，不会画出乱码）。
//   索引 ↔ 字符对照见同目录 cjk16_charset.txt。
// ============================================================================
module cjk16_font (
    input  wire [8:0] glyph,   // 字形索引 0..464
    input  wire [3:0] row,       // 行号 0..15（0 = 最上一行）
    output reg  [15:0] pixels    // 该行 16 个像素，bit15 = 最左
);

    always @(*) begin
        pixels = 16'h0000;         // 默认空白（未收录字形显示为空）
        case ({glyph, row})
            // 0: 日
            13'd0: pixels = 16'h0000;
            13'd1: pixels = 16'h3FF8;
            13'd2: pixels = 16'h3018;
            13'd3: pixels = 16'h3018;
            13'd4: pixels = 16'h3018;
            13'd5: pixels = 16'h3018;
            13'd6: pixels = 16'h3018;
